import './csvLogger.js';
import {PayloadStream} from './dataSource.js';
const $=id=>document.getElementById(id),workspace=document.querySelector('.workspace'),pane=document.createElement('section');pane.className='hardware hidden';pane.innerHTML=`
<div class="eyebrow">PAYLOAD v2 / HARDWARE INTEGRATION</div><h2 style="margin-top:12px">Hardware & firmware</h2><p class="lead">Your ESP32 + SX1278 link analyzer now feeds the mapper directly. Import its 23-column CSV, connect over Bluetooth LE or USB serial, or stream CSV from an existing secure WebSocket bridge.</p>
<div class="notice"><strong>Position is simulated in this firmware.</strong> The supplied sketch generates a serpentine path at a fixed 10 m altitude. RF measurements are real when received from hardware; the map position is synthetic until MAVLink is integrated. No-signal rows are timeout events with sentinel RSSI/SNR, not measured −130 dBm reception.</div>
<div class="hwcard" style="margin:20px 0"><h3>Automatic project CSV logging</h3><div id="csvlogstatus" class="hwstatus" role="status">Checking local logger…</div><button id="csvlogretry">Retry logger</button><p class="hint">Live reports, CSV imports, and demo surveys are saved in separate CSV session files under project_drone/data. Coordinates and RF readings stay together in each row. The local dashboard must be running. Wait for “Saved” before closing the page.</p></div><div class="hwgrid"><div class="hwcard wide"><h3>Latest payload report</h3><div class="hwlatest"><label>Quality score<b id="hwscore">—</b></label><label>Rolling loss · 50 outcomes<b id="hwloss">—</b></label><label>Fade margin<b id="hwfade">—</b></label><label>Reception<b id="hwrx">—</b></label></div><p class="hint" id="hwlatestnote">Load a payload CSV or connect a source.</p></div>
<div class="hwcard"><h3>Live data source</h3><div id="hwstatus" class="hwstatus" role="status">Disconnected · CSV upload available</div><button id="bleconnect" class="primary">Connect Bluetooth · ESP32</button><p class="hint" id="blesupport"></p><button id="serialconnect">Connect USB serial · 115200</button><button id="disconnect">Disconnect</button><p class="hint" id="serialsupport"></p><input id="wsurl" type="url" aria-label="Secure WebSocket URL" placeholder="wss://your-bridge.example/stream"><button id="wsconnect">Connect WebSocket</button><button id="hwupload">Upload CSV instead</button><p class="hint">Live sessions start a new survey. The map refreshes every 2 seconds, retaining at most 30,000 reports. Closing a connection retains the collected map. BLE reports are integrity-checked; delivery gaps are reported separately from LoRa packet loss. Bluetooth is live telemetry, not an onboard recorder. WebSocket requires your own CSV bridge; none is bundled.</p><p class="hint">In the sketch: <code>PRINT_CSV=1</code>. The original has CSV and SD disabled. Human-readable serial messages are ignored. SD import needs <code>ENABLE_SD=1</code> and matching wiring.</p></div>
<div class="hwcard"><h3>Configuration from supplied code</h3><div class="kv"><span>433 MHz</span><span>SF 7</span><span>BW 125 kHz</span><span>CR 4/5</span><span>Sync 0xA5</span><span>Preamble 8</span><span>CRC enabled</span><span>RSSI window 20</span><span>PDR window 50</span></div><p class="lead">Quality = 35% RSSI + 30% SNR + 35% packet delivery. Scores: excellent ≥80, good ≥60, fair ≥40, poor ≥20, dead zone &lt;20.</p><p class="hint">Sensitivity reference −123 dBm. TX power comes from the beacon packet; no beacon sketch was supplied. Current altitude: simulated 10 m. Serpentine spacing: 1 m east, 2 m north. These values describe firmware, not editable radio commands.</p></div>
<div class="hwcard wide"><h3>Payload firmware <span class="eyebrow">/ ESP32 DEVKIT V1 / BLE</span></h3><button id="copyfirmware">Copy sketch</button><a href="payload-ble.ino" download>Download BLE sketch</a> · <a href="payload-original.ino" download>Original, unchanged</a> · <a href="BleTelemetry.h" download>Download BleTelemetry.h</a> · <a href="payload-dashboard.ino" download>USB-only sketch</a><p class="hint">BLE variant: queued, checksummed telemetry; PRINT_CSV=1. Place BleTelemetry.h alongside the BLE sketch. SD remains disabled unless ENABLE_SD=1. Target: Arduino-ESP32 3.3.0, ESP32 Dev Module / DevKit V1; LoRa library by Sandeep Mistry. Built-in BLE library is used. Firmware compilation and physical hardware have not been tested here.</p><pre><code id="firmwarecode">Loading firmware…</code></pre></div>
<div class="hwcard"><h3>Ra-02 / SX1278 pinout</h3><table><tr><th>Signal</th><th>ESP32 GPIO</th></tr><tr><td>SCK</td><td>18</td></tr><tr><td>MISO</td><td>19</td></tr><tr><td>MOSI</td><td>23</td></tr><tr><td>NSS / CS</td><td>5</td></tr><tr><td>RST</td><td>22</td></tr><tr><td>DIO0</td><td>4</td></tr><tr><td>LED</td><td>2</td></tr></table><p class="hint">Optional SD (HSPI): SCK 25, MISO 26, MOSI 27, CS 33. Ra-02 wiring uses 3.3 V and common ground. No MAVLink UART is configured in this sketch.</p></div>
<div class="hwcard"><h3>Beacon firmware</h3><pre><code>// No beacon firmware supplied.
// Paste ESP32 beacon code here once ready.
// Payload expects: BCN,&lt;counter&gt;,&lt;tx_dbm&gt;
// Match frequency, SF, BW, CR, sync word,
// preamble and CRC settings above.</code></pre><h3>Import behavior</h3><p class="lead">Both the original 7-column survey schema and the full v2 schema are accepted. Quality fields remain available on received reports. Counter gaps are counted within each ordered session, excluding duplicate IDs and timeout rows. Counter decreases begin a new segment.</p><p class="hint">Rolling firmware loss and whole-survey inferred packet loss are different measures. Timeout duration alone does not reveal the number of lost packets. Timeout markers use red wireframe diamonds and are excluded from RSSI/SNR interpolation.</p></div></div>`;
workspace.after(pane);const tabs=[...document.querySelectorAll('nav button')],hwtab=document.querySelector('[data-stage="3"]');hwtab.removeAttribute('data-stage');hwtab.innerHTML='Hardware & firmware <small>PAYLOAD v2</small>';function show(hardware){workspace.classList.toggle('hidden',hardware);pane.classList.toggle('hidden',!hardware);tabs.forEach(t=>t.classList.remove('selected'));(hardware?hwtab:tabs[0]).classList.add('selected');document.dispatchEvent(new CustomEvent('app-view',{detail:hardware?'hardware':'map'}));}hwtab.onclick=()=>show(true);tabs[0].onclick=()=>show(false);$('hwupload').onclick=()=>{show(false);$('file').click();};
const warning=document.createElement('p');warning.className='surveywarning';$('filename').after(warning);
document.addEventListener('survey-loaded',e=>{const rows=e.detail.rows,p=rows.at(-1),payload=p?.source==='payload-v2';warning.textContent=payload?'PAYLOAD v2 · SIMULATED GPS · fixed 10 m. Red diamonds mark no-signal events; sentinel values are excluded from interpolation.':'';if(!payload){for(const id of ['hwscore','hwloss','hwfade','hwrx'])$(id).textContent='—';$('hwlatestnote').textContent='Current survey is not a payload v2 capture.';return;}$('hwscore').textContent=p.score+'/100';$('hwloss').textContent=p.loss_pct.toFixed(1)+'%';$('hwfade').textContent=p.received?p.fade_margin_db.toFixed(1)+' dB':'—';$('hwrx').textContent=p.received?'RECEIVED':'TIMEOUT';$('hwlatestnote').textContent=`${p.level} · counter ${p.Packet_ID} · ${p.Timestamp_ms} ms · TX ${p.received?p.tx_dbm+' dBm':'unknown'} · simulated position`;
});
let stream=null;const status=s=>$('hwstatus').textContent=s;
async function stop(){if(stream){await stream.disconnect();stream=null;}status('Disconnected');}
async function start(kind){try{await stop();status('Connecting…');const next=new PayloadStream(row=>document.dispatchEvent(new CustomEvent('payload-row',{detail:row})),status);stream=next;document.dispatchEvent(new CustomEvent('payload-session',{detail:{transport:kind==='socket'?'websocket':kind==='bluetooth'?'bluetooth':'serial'}}));if(kind==='bluetooth')await next.connectBluetooth();else if(kind==='serial')await next.connectSerial();else next.connectSocket($('wsurl').value.trim());}catch(e){status(e.message);}}
$('bleconnect').onclick=()=>start('bluetooth');$('blesupport').textContent=navigator.bluetooth?'Flash the BLE sketch, then select RF-Payload-V2. Reports automatically save to CSV in the local dashboard.':'Web Bluetooth is unavailable here. Open http://127.0.0.1:4174 in Chrome/Edge.';$('bleconnect').disabled=!navigator.bluetooth;
$('serialconnect').onclick=()=>start('serial');$('wsconnect').onclick=()=>start('socket');$('disconnect').onclick=stop;$('serialsupport').textContent=navigator.serial?'Web Serial detected. Use a direct Chromium tab if the embedded browser blocks device access.':'Web Serial unavailable in this browser. Open in Chrome/Edge or upload CSV.';$('serialconnect').disabled=!navigator.serial;
for(const id of ['file','demo','emptydemo'])$(id).addEventListener(id==='file'?'change':'click',()=>{stop();document.dispatchEvent(new CustomEvent('payload-session'));});
let firmware='';fetch('payload-ble.ino').then(r=>{if(!r.ok)throw Error('Firmware unavailable');return r.text();}).then(t=>{firmware=t;$('firmwarecode').replaceChildren();for(const line of t.split('\n')){const span=document.createElement('span');span.className=line.trim().startsWith('//')?'comment':line.trim().startsWith('#')?'directive':'';span.textContent=line+'\n';$('firmwarecode').append(span);}}).catch(e=>$('firmwarecode').textContent=e.message);$('copyfirmware').onclick=async()=>{try{if(!firmware)throw Error('Firmware still loading');await navigator.clipboard.writeText(firmware);$('copyfirmware').textContent='Copied';}catch{$('copyfirmware').textContent='Use download link';}};

const csvSidebar=document.createElement('p');csvSidebar.className='hint';$('filename').after(csvSidebar);document.addEventListener('csv-log-status',e=>{csvSidebar.textContent=e.detail.message;csvSidebar.style.color=e.detail.error?'#ff9b88':'';const el=$('csvlogstatus');el.textContent=e.detail.message;el.style.color=e.detail.error?'#ff9b88':'';});$('csvlogretry').onclick=()=>document.dispatchEvent(new CustomEvent('csv-log-retry'));
